		LmdbValue value = publication.ready(revision, LmdbValue.UNKNOWN_ID);
		assertEquals(LmdbValue.UNKNOWN_ID, value.getInternalID());
		assertEquals(publication.read(publication.ready(revision, VALUE_ID)), publication.read(value));
